export const PIXEL_ART=art;
export const SPRITES={};
export function initSprites(theme='natural'){
 const leafPalettes={fantasy:{g:'#655079',G:'#9b77b3',L:'#d9afd4'},nocturne:{g:'#31575b',G:'#4b8286',L:'#8dc6bc'},copper:{g:'#87613c',G:'#bb8745',L:'#e3b65c'}};
 for(const [name,rows] of Object.entries(art)){
  const frames=[];
  for(let f=0;f<2;f++){const canvas=document.createElement('canvas');canvas.width=16;canvas.height=16;const c=canvas.getContext('2d');
   rows.forEach((row,y)=>[...row].forEach((ch,x)=>{if(ch==='.')return;let dy=y;if(f&&name==='rabbit'&&y<6)dy=y-1;if(f&&['bee','firefly'].includes(name)&&y<7)dy=y-1;if(f&&name==='fox'&&y===12)dy=y-1;c.fillStyle=['tree','shrub','grass'].includes(name)&&leafPalettes[theme]?.[ch]?leafPalettes[theme][ch]:name==='fox'&&ch==='R'?'#eda35d':colors[ch]||'#ff00ff';c.fillRect(x,dy,1,1);}));frames.push(canvas);
  }SPRITES[name]=frames;
 }
}
export function sprite(ctx,name,x,y,size=16,frame=0,flip=false,alpha=1){const source=SPRITES[name]?.[frame%2];if(!source)return;ctx.save();ctx.globalAlpha=alpha;ctx.imageSmoothingEnabled=false;if(flip){ctx.translate(x+size,y);ctx.scale(-1,1);ctx.drawImage(source,0,0,size,size);}else ctx.drawImage(source,x,y,size,size);ctx.restore();}
